2	import { supabase } from '../utils/supabase';
3	import { getMember, addRoleToMember, removeRoleFromMember } from '../utils/discord';
4	import { logger } from '../utils/logger';
5	import { RolesSyncRequest, RolesSyncResponse } from '../types/api';
6	import { Member, GenerationRole, Team, MemberTeamRelation, TeamLeader } from '../types/database';
7	
8	export const syncRoles = async (req: Request, res: Response): Promise<void> => {
9	  try {
10	    const { discord_uid } = req.body as RolesSyncRequest;
11	
12	    if (!discord_uid) {
13	      res.status(400).json({ success: false, error: 'discord_uid is required' });
14	      return;
15	    }
16	
17	    // Discordメンバーを取得
18	    const member = await getMember(discord_uid);
19	    if (!member) {
20	      res.status(404).json({ success: false, error: 'Discord member not found' });
21	      return;
22	    }
23	
24	    // DBから部員情報を取得
25	    const { data: memberData, error: memberError } = await supabase
26	      .from('members')
27	      .select('*')
28	      .eq('discord_uid', discord_uid)
29	      .single<Member>();
30	
31	    if (memberError || !memberData) {
32	      logger.error('Failed to fetch member from DB', memberError);
33	      res.status(404).json({ success: false, error: 'Member not found in database' });
34	      return;
35	    }
36	
37	    const rolesAssigned: string[] = [];
38	    const rolesRemoved: string[] = [];
39	
40	    // 1. 期生ロールの同期
41	    const { data: generationRole } = await supabase
42	      .from('generation_roles')
43	      .select('*')
44	      .eq('generation', memberData.generation)
45	      .single<GenerationRole>();
46	
47	    if (generationRole) {
48	      // 期生ロールを付与
49	      const hasRole = member.roles.cache.has(generationRole.discord_role_id);
50	      if (!hasRole) {
51	        await addRoleToMember(member, generationRole.discord_role_id);
52	        rolesAssigned.push(`${memberData.generation}期生`);
53	      }
54	
55	      // 他の期生ロールを削除
56	      const { data: allGenerationRoles } = await supabase
57	        .from('generation_roles')
58	        .select('*')
59	        .neq('generation', memberData.generation);
60	
61	      if (allGenerationRoles) {
62	        for (const otherGenRole of allGenerationRoles) {
63	          if (member.roles.cache.has(otherGenRole.discord_role_id)) {
64	            await removeRoleFromMember(member, otherGenRole.discord_role_id);
65	            rolesRemoved.push(`${otherGenRole.generation}期生`);
66	          }
67	        }
68	      }
69	    }
70	
71	    // 2. 班ロールの同期
72	    // メンバーが所属する班を取得
73	    const { data: memberTeams } = await supabase
74	      .from('member_team_relations')
75	      .select('team_id')
76	      .eq('member_id', memberData.supabase_auth_user_id);
77	
78	    const teamIds = memberTeams?.map((mt: { team_id: string }) => mt.team_id) || [];
79	
80	    // 所属班のロールを取得
81	    const { data: teams } = await supabase
82	      .from('teams')
83	      .select('*')
84	      .in('id', teamIds);
85	
86	    const teamRoleIds = teams?.map((t: Team) => t.discord_role_id) || [];
87	
88	    // 所属班のロールを付与
89	    for (const team of teams || []) {
90	      if (!member.roles.cache.has(team.discord_role_id)) {
91	        await addRoleToMember(member, team.discord_role_id);
92	        rolesAssigned.push(team.name);
93	      }
94	    }
95	
96	    // 全ての班を取得
97	    const { data: allTeams } = await supabase.from('teams').select('*');
98	
99	    // 所属していない班のロールを削除
100	    for (const team of allTeams || []) {
101	      if (
102	        !teamRoleIds.includes(team.discord_role_id) &&
103	        member.roles.cache.has(team.discord_role_id)
104	      ) {
105	        await removeRoleFromMember(member, team.discord_role_id);
106	        rolesRemoved.push(team.name);
107	      }
108	    }
109	
110	    // 3. 班長ロールの同期
111	    const leaderRoleId = process.env.DISCORD_LEADER_ROLE_ID;
112	    if (leaderRoleId) {
113	      const { data: isLeader } = await supabase
114	        .from('team_leaders')
115	        .select('*')
116	        .eq('member_id', memberData.supabase_auth_user_id)
117	        .single<TeamLeader>();
118	
119	      if (isLeader) {
120	        // 班長ロールを付与
121	        if (!member.roles.cache.has(leaderRoleId)) {
122	          await addRoleToMember(member, leaderRoleId);
123	          rolesAssigned.push('班長');
124	        }
125	      } else {
126	        // 班長ロールを削除
127	        if (member.roles.cache.has(leaderRoleId)) {
128	          await removeRoleFromMember(member, leaderRoleId);
129	          rolesRemoved.push('班長');
130	        }
131	      }
132	    }
133	
134	    // 4. Status別ロールの同期（中学生/高校生/OB）
135	    const jhRoleId = process.env.DISCORD_JH_ROLE_ID;
136	    const hRoleId = process.env.DISCORD_H_ROLE_ID;
137	    const obRoleId = process.env.DISCORD_OB_ROLE_ID;
138	    const statusRoleIds = [jhRoleId, hRoleId, obRoleId].filter(Boolean) as string[];
139	
140	    // 現在のstatusに応じたロールを決定
141	    let targetStatusRoleId: string | null = null;
142	    let statusRoleName = '';
143	
144	    if (memberData.status === 0 && jhRoleId) {
145	      targetStatusRoleId = jhRoleId;
146	      statusRoleName = '中学生';
147	    } else if (memberData.status === 1 && hRoleId) {
148	      targetStatusRoleId = hRoleId;
149	      statusRoleName = '高校生';
150	    } else if (memberData.status === 2 && obRoleId) {
151	      targetStatusRoleId = obRoleId;
152	      statusRoleName = 'OB';
153	    }
154	
155	    // 正しいstatusロールを付与
156	    if (targetStatusRoleId) {
157	      if (!member.roles.cache.has(targetStatusRoleId)) {
158	        await addRoleToMember(member, targetStatusRoleId);
159	        rolesAssigned.push(statusRoleName);
160	      }
161	    }
162	
163	    // 他のstatusロールを削除
164	    for (const roleId of statusRoleIds) {
165	      if (roleId !== targetStatusRoleId && member.roles.cache.has(roleId)) {
166	        await removeRoleFromMember(member, roleId);
167	        const removedName = roleId === jhRoleId ? '中学生' : roleId === hRoleId ? '高校生' : 'OB';
168	        rolesRemoved.push(removedName);
169	      }
170	    }
171	
172	    // 5. 部員ロール（MEMBERロール）の同期
173	    const memberRoleId = process.env.DISCORD_MEMBER_ROLE_ID;
174	    if (memberRoleId) {
175	      // status 0 or 1（中学生・高校生）の場合のみ付与
176	      if (memberData.status === 0 || memberData.status === 1) {
177	        if (!member.roles.cache.has(memberRoleId)) {
178	          await addRoleToMember(member, memberRoleId);
179	          rolesAssigned.push('部員');
180	        }
181	      } else {
182	        // status 2（OB）の場合は削除
183	        if (member.roles.cache.has(memberRoleId)) {
184	          await removeRoleFromMember(member, memberRoleId);
185	          rolesRemoved.push('部員');
186	        }
187	      }
188	    }
189	
190	    // 6. 認証済みロール（VERIFIEDロール）の付与
191	    const verifiedRoleId = process.env.DISCORD_VERIFIED_ROLE_ID;
192	    if (verifiedRoleId) {
193	      // DBに登録されていれば付与
194	      if (!member.roles.cache.has(verifiedRoleId)) {
195	        await addRoleToMember(member, verifiedRoleId);
196	        rolesAssigned.push('認証済み');
197	      }
198	    }
199	
200	    const response: RolesSyncResponse = {
201	      success: true,
202	      roles_assigned: rolesAssigned,
203	      roles_removed: rolesRemoved,
204	    };
205	
206	    logger.info(`Roles synced for ${discord_uid}`, response);
207	    res.json(response);
208	  } catch (error) {
209	    logger.error('Error in syncRoles', error);
210	    res.status(500).json({ success: false, error: 'Internal server error' });
211	  }
212	};
